\]
\[
\begin{aligned}
0
&= \frac{d}{dm} \sum_{i=1}^n \left\{ * \right\}{ Y_i - m }^2  \ \ \mid_{m=\hat\mu}  
&&= \sum_{i=1}^n \frac{d}{dm} \left\{ * \right\}{ Y_i - m }^2  \ \ \mid_{m=\hat\mu}  \\
&= \sum_{i=1}^n -2 \left\{ * \right\}{ Y_i - m } \ \ \mid_{m=\hat\mu}
&&= \sum_{i=1}^n -2 \left\{ * \right\}{ Y_i - \hat\mu }
